Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to translate:
<original_code>
import java.io.*;

public class Main {
    private static int nextInt(InputStream is) throws IOException {
        int c = is.read();
        while (c <= ' ') {
            c = is.read();
        }
        boolean negative = false;
        if (c == '-') {
            negative = true;
            c = is.read();
        } else if (c == '+') {
            c = is.read();
        }
        int number = 0;
        while (c > ' ') {
            number = number * 10 + (c - '0');
            c = is.read();
        }
        return negative ? -number : number;
    }

    public static void main(String[] args) throws IOException {
        InputStream in = System.in;
        int w = nextInt(in);
        int m = nextInt(in);
        PrintWriter out = new PrintWriter(System.out);
        boolean ok = true;
        while (m > 0) {
            int rem = m % w;
            if (rem == 0 || rem == 1) {
                m /= w;
            } else if (rem == w - 1) {
                m++;
            } else {
                ok = false;
                break;
            }
        }
        out.println(ok ? "YES" : "NO");
        out.flush();
    }
}
